import re

# Let me re-extract the data with correct column indexing
def extract_fiscal_year_data(fname, years_needed):
    with open('/app/resources/' + fname, 'r') as f:
        content = f.read()

    # Find the table with Department of Energy and Agriculture
    start = content.find('<table><tr><th>Fiscal year')
    if start == -1:
        return {}
    end = content.find('</table>', start)
    table = content[start:end]

    # Extract all fiscal year rows (4-digit years)
    # Pattern: <tr><td>YEAR</td><td>value1</td><td>value2</td>...
    pattern = r'<tr><td>(\d{4})</td>(<td[^>]*>([\d,-]+)</td>)+'
    matches = re.findall(pattern, table)

    result = {}
    for match in matches:
        year = int(match[0])
        if year in years_needed:
            # Get all the td values
            values = re.findall(r'<td[^>]*>([\d,-]+)</td>', match[0])
            # Values are: Legislative(1), Judicial(2), Agriculture(3), Commerce(4), Defense(5), Education(6), Energy(7), ...
            # But we need to match correctly - the header has (1), (2), etc.
            if len(values) >= 7:
                agriculture = int(values[2].replace(',', ''))  # Column 3 (index 2)
                energy = int(values[6].replace(',', ''))  # Column 7 (index 6)
                result[year] = {'Agriculture': agriculture, 'Energy': energy}
    return result

# Get data from each file
data_2016 = extract_fiscal_year_data('treasury_bulletin_2016_12.json', [2012, 2013, 2014, 2015])
print("From 2016 bulletin:", data_2016)

data_2017 = extract_fiscal_year_data('treasury_bulletin_2017_12.json', [2013, 2014, 2015, 2016, 2017])
print("From 2017 bulletin:", data_2017)

data_2020 = extract_fiscal_year_data('treasury_bulletin_2020_12.json', [2016, 2017, 2018, 2019])
print("From 2020 bulletin:", data_2020)

# Combine data - use most recent bulletin for overlapping years
all_years = {}
for year in range(2012, 2020):
    if year in data_2020:
        all_years[year] = data_2020[year]
    elif year in data_2017:
        all_years[year] = data_2017[year]
    elif year in data_2016:
        all_years[year] = data_2016[year]

print("\nCombined data for FY 2012-2019:")
for year in sorted(all_years.keys()):
    print(f"  {year}: Agriculture={all_years[year]['Agriculture']}, Energy={all_years[year]['Energy']}")
