python3 << 'EOF'
import json
import re

def extract_data(fname, years_needed):
    with open('/app/resources/' + fname, 'r') as f:
        data = json.load(f)

    result = {}
    for elem in data['document']['elements']:
        if elem.get('type') == 'table':
            content = str(elem.get('content', ''))
            if 'Department of Energy' in content and 'Department of Agriculture' in content and 'Fiscal year' in content:
                lines = content.split('</tr>')
                for line in lines:
                    # Match rows with 4-digit years
                    year_match = re.search(r'<td>(\d{4})</td>', line)
                    if year_match:
                        year = int(year_match.group(1))
                        if year in years_needed:
                            values = re.findall(r'<td[^>]*>([\d,\-]+)</td>', line)
                            if len(values) >= 8:
                                agriculture = int(values[3].replace(',', ''))  # Column 4 (0-indexed 3)
                                energy = int(values[7].replace(',', ''))       # Column 8 (0-indexed 7)
                                result[year] = {'Agriculture': agriculture, 'Energy': energy}
                break
    return result

# Extract from each file - years needed
data_2016 = extract_data('treasury_bulletin_2016_12.json', [2012, 2013, 2014, 2015])
print("2016 bulletin (FY2012-2015):", data_2016)

data_2017 = extract_data('treasury_bulletin_2017_12.json', [2016, 2017])
print("2017 bulletin (FY2016-2017):", data_2017)

data_2020 = extract_data('treasury_bulletin_2020_12.json', [2016, 2017, 2018, 2019])
print("2020 bulletin (FY2016-2019):", data_2020)

# Combine - prefer newer bulletin for overlapping years
all_data = {}
for year in range(2012, 2020):
    if year in data_2020:
        all_data[year] = data_2020[year]
    elif year in data_2017:
        all_data[year] = data_2017[year]
    elif year in data_2016:
        all_data[year] = data_2016[year]

print("\n=== Final Data FY 2012-2019 ===")
for year in sorted(all_data.keys()):
    print(f"FY{year}: Agriculture={all_data[year]['Agriculture']}, Energy={all_data[year]['Energy']}")
EOF
